// nppiIntegral / nppiSqrIntegral family executor (package s1).
//
// Host-visible surface: entry-point templates are declared here and defined +
// explicitly instantiated in nppi_integral_executor.cu.  The public wrappers
// are generated by mpp_scripts/gen_family.py
// (mpp_scripts/families/nppi_integral.json).
//
// Semantics (NVIDIA NPP header contract, pinned by differential tests):
//   * pDst(j, i) = nVal + sum_{l < j, k < i} pSrc(l, k); the destination image
//     is (W+1) x (H+1) for a W x H source ROI.
//   * nppiSqrIntegral additionally computes pSqr(j, i) = nValSqr + sum pSrc^2
//     over the same rectangle, also (W+1) x (H+1).
//   * Row/column scan kernels accumulate in int64 (integral destinations) or
//     double (floating destinations) so 8-bit inputs are exact.
#ifndef NPPI_INTEGRAL_EXECUTOR_H
#define NPPI_INTEGRAL_EXECUTOR_H

#include "npp.h"

namespace nppi {
namespace statistics {

template <typename SrcT, typename DstT>
NppStatus runIntegral(const SrcT *pSrc, int nSrcStep, DstT *pDst, int nDstStep, NppiSize oROI, DstT nVal,
                      cudaStream_t stream);

template <typename SrcT, typename DstT, typename SqrT>
NppStatus runSqrIntegral(const SrcT *pSrc, int nSrcStep, DstT *pDst, int nDstStep, SqrT *pSqr, int nSqrStep,
                         NppiSize oSrcROI, DstT nVal, SqrT nValSqr, cudaStream_t stream);

}  // namespace statistics
}  // namespace nppi

#endif  // NPPI_INTEGRAL_EXECUTOR_H
